+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, existsSync, unlinkSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join, dirname } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { execFileSync } from 'node:child_process';
+import { scaffold } from '../../scaffold/scaffold.mjs';
+import { PROFILES } from '../profiles.mjs';
+
+const __dirname = dirname(fileURLToPath(import.meta.url));
+const templatesDir = join(__dirname, '..', '..', 'scaffold', 'templates');
+const manifestPath = join(__dirname, '..', '..', 'scaffold', 'manifest.json');
+
+function git(dir, args) { execFileSync('git', args, { cwd: dir, encoding: 'utf8' }); }
+
+// gen-contract is a no-op stub in scaffold; "drift" is simulated by uncommitted
+// changes already present in _generated when check-drift runs.
+function setupRepo() {
+  const dir = mkdtempSync(join(tmpdir(), 'hs-drift-'));
+  scaffold(PROFILES.full, { templatesDir, manifestPath, targetDir: dir });
+  git(dir, ['init', '-q']);
+  git(dir, ['config', 'user.email', 't@t']);
+  git(dir, ['config', 'user.name', 't']);
+  const gen = join(dir, 'backend', 'binary_prediction', 'orders', '_generated');
+  mkdirSync(gen, { recursive: true });
+  writeFileSync(join(gen, 'api.py'), 'X = 1\n');
+  git(dir, ['add', '-A']);
+  git(dir, ['commit', '-qm', 'init']);
+  return { dir, genFile: join(gen, 'api.py') };
+}
+
+function runCheckDrift(dir) {
+  try {
+    execFileSync('make', ['check-drift'], { cwd: dir, encoding: 'utf8' });
+    return 0;
+  } catch (e) {
+    return e.status ?? 1;
+  }
+}
+
+test('check-drift: clean tree exits 0', () => {
+  const { dir } = setupRepo();
+  assert.equal(runCheckDrift(dir), 0);
+});
+
+test('check-drift: modified committed generated file -> fail + restore', () => {
+  const { dir, genFile } = setupRepo();
+  writeFileSync(genFile, 'X = 999\n');
+  assert.notEqual(runCheckDrift(dir), 0);
+  assert.equal(readFileSync(genFile, 'utf8'), 'X = 1\n', 'tree must be restored to committed state');
+});
+
+test('check-drift: untracked new generated file -> fail + clean', () => {
+  const { dir } = setupRepo();
+  const extra = join(dir, 'backend', 'binary_prediction', 'orders', '_generated', 'extra.py');
+  writeFileSync(extra, 'Y = 2\n');
+  assert.notEqual(runCheckDrift(dir), 0);
+  assert.equal(existsSync(extra), false, 'untracked generated file must be cleaned');
+});
+
+test('check-drift: deleted committed generated file -> fail + restored', () => {
+  // Exercises the guarded-checkout path: git diff --name-only HEAD detects the deletion
+  // and git checkout HEAD -- restores it (no 2>/dev/null || true masking).
+  const { dir, genFile } = setupRepo();
+  unlinkSync(genFile);
+  assert.notEqual(runCheckDrift(dir), 0);
+  assert.ok(existsSync(genFile), 'deleted committed generated file must be restored');
+  assert.equal(readFileSync(genFile, 'utf8'), 'X = 1\n', 'restored content must match committed state');
+});

