+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { mkdtempSync, writeFileSync, existsSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join, dirname } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { execFileSync } from 'node:child_process';
+import { scaffold } from '../../scaffold/scaffold.mjs';
+import { PROFILES } from '../profiles.mjs';
+
+const __dirname = dirname(fileURLToPath(import.meta.url));
+const templatesDir = join(__dirname, '..', '..', 'scaffold', 'templates');
+const manifestPath = join(__dirname, '..', '..', 'scaffold', 'manifest.json');
+
+// Two distinct minimal contracts — content validity is irrelevant (tools are faked);
+// they only need to differ so `cmp -s` sees a change.
+const V1 = '{"openapi":"3.1.0","info":{"title":"x","version":"1"},"paths":{}}\n';
+const V2 = '{"openapi":"3.1.0","info":{"title":"x","version":"2"},"paths":{}}\n';
+
+function git(dir, args) { execFileSync('git', args, { cwd: dir, encoding: 'utf8' }); }
+
+// Fake tool: records its invocation to <marker> in cwd, then exits <code>.
+// $(SPECTRAL)/$(OASDIFF) expand to this; the trailing make args (lint / breaking …)
+// land as positional params on the inner `sh -c` and are ignored.
+const tool = (marker, code) => `sh -c 'echo ran >> ${marker}; exit ${code}' --`;
+const SPEC_OK = tool('.spec-ran', 0);
+const SPEC_FAIL = tool('.spec-ran', 1);
+const OAS_OK = tool('.oas-ran', 0);
+const OAS_FAIL = tool('.oas-ran', 1);
+
+// Scaffold a full profile into a fresh git repo. withContract commits openapi.json=V1
+// and branches a local `base` at that commit; without it, base has no contract.
+function setupRepo({ withContract = true } = {}) {
+  const dir = mkdtempSync(join(tmpdir(), 'hs-cv-'));
+  scaffold(PROFILES.full, { templatesDir, manifestPath, targetDir: dir });
+  git(dir, ['init', '-q']);
+  git(dir, ['config', 'user.email', 't@t']);
+  git(dir, ['config', 'user.name', 't']);
+  if (withContract) writeFileSync(join(dir, 'openapi.json'), V1);
+  git(dir, ['add', '-A']);
+  git(dir, ['commit', '-qm', 'init']);
+  git(dir, ['branch', 'base']);
+  return dir;
+}
+
+// Run `make contract-validate` with fake tools + local base branch; return exit status.
+function run(dir, overrides = {}) {
+  const env = {
+    ...process.env,
+    CONTRACT_FETCH: 'true',     // no-op: temp repo has no remote
+    CONTRACT_BASE_REF: 'base',  // local branch (also exercises the host-tunable var)
+    SPECTRAL: SPEC_OK,
+    OASDIFF: OAS_OK,
+    ...overrides,
+  };
+  try {
+    execFileSync('make', ['contract-validate'], { cwd: dir, encoding: 'utf8', env });
+    return 0;
+  } catch (e) {
+    return e.status ?? 1;
+  }
+}
+
+const ran = (dir, marker) => existsSync(join(dir, marker));
+
+test('no contract: exits 0, neither tool runs', () => {
+  // Guards the single-shell-block fix: line-1 `exit 0` must short-circuit the WHOLE recipe.
+  const dir = setupRepo({ withContract: false });
+  assert.equal(run(dir), 0);
+  assert.equal(ran(dir, '.spec-ran'), false, 'spectral must not run when no contract');
+  assert.equal(ran(dir, '.oas-ran'), false, 'oasdiff must not run when no contract');
+});
+
+test('unchanged contract: exits 0, neither tool runs', () => {
+  const dir = setupRepo();              // working openapi.json == base
+  assert.equal(run(dir), 0);
+  assert.equal(ran(dir, '.spec-ran'), false, 'spectral must not run when unchanged');
+  assert.equal(ran(dir, '.oas-ran'), false, 'oasdiff must not run when unchanged');
+});
+
+test('changed contract, both tools pass: exits 0', () => {
+  const dir = setupRepo();
+  writeFileSync(join(dir, 'openapi.json'), V2);   // differs from base
+  assert.equal(run(dir), 0);
+  assert.ok(ran(dir, '.spec-ran'), 'spectral must run on change');
+  assert.ok(ran(dir, '.oas-ran'), 'oasdiff must run on change with a base');
+});
+
+test('spectral violation: non-zero exit', () => {
+  const dir = setupRepo();
+  writeFileSync(join(dir, 'openapi.json'), V2);
+  assert.notEqual(run(dir, { SPECTRAL: SPEC_FAIL }), 0);
+});
+
+test('oasdiff breaking change: non-zero exit', () => {
+  const dir = setupRepo();
+  writeFileSync(join(dir, 'openapi.json'), V2);   // spectral passes, oasdiff fails
+  assert.notEqual(run(dir, { OASDIFF: OAS_FAIL }), 0);
+});
+
+test('new contract (base resolves, no contract there): spectral only, exits 0', () => {
+  const dir = setupRepo({ withContract: false });   // base has no openapi.json
+  writeFileSync(join(dir, 'openapi.json'), V1);     // working tree introduces it
+  assert.equal(run(dir), 0);
+  assert.ok(ran(dir, '.spec-ran'), 'spectral must run on a new contract');
+  assert.equal(ran(dir, '.oas-ran'), false, 'oasdiff must not run without a base contract');
+});
+
+test('unresolved base ref: non-zero exit', () => {
+  const dir = setupRepo();
+  writeFileSync(join(dir, 'openapi.json'), V2);
+  assert.notEqual(run(dir, { CONTRACT_BASE_REF: 'no-such-ref' }), 0);
+});
+
+test('fetch failure: non-zero exit', () => {
+  const dir = setupRepo();
+  writeFileSync(join(dir, 'openapi.json'), V2);
+  assert.notEqual(run(dir, { CONTRACT_FETCH: 'false' }), 0);
+});
+
+test('tree invariant: .contract-base.json is cleaned up after a run', () => {
+  const dir = setupRepo();
+  writeFileSync(join(dir, 'openapi.json'), V2);
+  assert.equal(run(dir), 0);
+  assert.equal(existsSync(join(dir, '.contract-base.json')), false,
+    'base extraction temp file must be removed by the trap');
+});

