+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { execFileSync } from 'node:child_process';
+import { mkdtempSync, readFileSync, readdirSync, statSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join, dirname, relative } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { PROFILES } from '../profiles.mjs';
+
+const __dirname = dirname(fileURLToPath(import.meta.url));
+const scaffoldMjs = join(__dirname, '..', '..', 'scaffold', 'scaffold.mjs');
+const setupMjs = join(__dirname, '..', '..', 'scaffold', 'setup.mjs');
+
+function walk(dir, base = dir, acc = []) {
+  for (const name of readdirSync(dir)) {
+    const full = join(dir, name);
+    if (statSync(full).isDirectory()) walk(full, base, acc);
+    else acc.push(relative(base, full).split('\\').join('/'));
+  }
+  return acc.sort();
+}
+
+for (const name of ['full', 'be-only']) {
+  test(`init 2-call (scaffold + setup --from-answers) reproduces golden: ${name}`, () => {
+    const answers = JSON.stringify(PROFILES[name]);
+    const target = mkdtempSync(join(tmpdir(), `init2call-${name}-`));
+    execFileSync('node', [scaffoldMjs, '--target', target, '--answers', answers]);
+    execFileSync('node', [setupMjs, '--target', target, '--from-answers', answers]);
+    const goldenDir = join(__dirname, '..', 'golden', name);
+    const expected = walk(goldenDir);
+    assert.deepEqual(walk(target), expected, 'file set differs from golden');
+    for (const rel of expected) {
+      assert.ok(
+        readFileSync(join(goldenDir, rel)).equals(readFileSync(join(target, rel))),
+        `content differs: ${rel}`,
+      );
+    }
+  });
+}
+
+test('init 2-call resolves standardVersion from plugin.json when omitted', () => {
+  const { standardVersion, ...answers } = PROFILES.full;
+  const json = JSON.stringify(answers);
+  const target = mkdtempSync(join(tmpdir(), 'init2call-ver-'));
+  execFileSync('node', [scaffoldMjs, '--target', target, '--answers', json]);
+  execFileSync('node', [setupMjs, '--target', target, '--from-answers', json]);
+  const pj = JSON.parse(readFileSync(join(__dirname, '..', '..', '.claude-plugin', 'plugin.json'), 'utf8'));
+  const cfg = JSON.parse(readFileSync(join(target, '.claude', 'house-standard.config.json'), 'utf8'));
+  assert.equal(cfg.standardVersion, pj.version);
+});
